p=Path('style.css');s=p.read_text(encoding='utf-8').replace('.liquid-tail{opacity:.95}', '.liquid-tail{opacity:.78}').replace('drop-shadow(0 0 4px #f6c55c)','drop-shadow(0 0 2px #f6c55c99)');p.write_text(s,encoding='utf-8')
